Extensions.ExtractScript:
param(
    [xml] $Document
);

foreach( $file in $Document.unattend.Extensions.File ) {
    $path = [System.Environment]::ExpandEnvironmentVariables( $file.GetAttribute( 'path' ) );
    mkdir -Path( $path | Split-Path -Parent ) -ErrorAction 'SilentlyContinue';
    $encoding = switch( [System.IO.Path]::GetExtension( $path ) ) {
        { $_ -in '.ps1', '.xml' } { [System.Text.Encoding]::UTF8; }
        { $_ -in '.reg', '.vbs', '.js' } { [System.Text.UnicodeEncoding]::new( $false, $true ); }
        default { [System.Text.Encoding]::Default; }
    };
    $bytes = $encoding.GetPreamble() + $encoding.GetBytes( $file.InnerText.Trim() );
    [System.IO.File]::WriteAllBytes( $path, $bytes );
}

Extensions.File:
$scripts = @(
	{
		net.exe accounts /maxpwage:UNLIMITED;
	};
	{
		reg.exe add "HKLM\Software\Policies\Microsoft\Windows\CloudContent" /v "DisableCloudOptimizedContent" /t REG_DWORD /d 1 /f;
		[System.Diagnostics.EventLog]::CreateEventSource( 'UnattendGenerator', 'Application' );
	};
	{
		Register-ScheduledTask -TaskName 'UnlockStartLayout' -Xml $( Get-Content -LiteralPath 'C:\Windows\Setup\Scripts\UnlockStartLayout.xml' -Raw );
	};
	{
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows Defender Security Center\Notifications" /v DisableNotifications /t REG_DWORD /d 1 /f;
	};
	{
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\CI\Policy" /v VerifiedAndReputablePolicyState /t REG_DWORD /d 0 /f;
	};
	{
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer" /v SmartScreenEnabled /t REG_SZ /d "Off" /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\WTDS\Components" /v ServiceEnabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\WTDS\Components" /v NotifyMalicious /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\WTDS\Components" /v NotifyPasswordReuse /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\WTDS\Components" /v NotifyUnsafeApp /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows Defender Security Center\Systray" /v HideSystray /t REG_DWORD /d 1 /f;
	};
	{
		# Keep UAC structurally ENABLED (EnableLUA=1, the default) so
		# UWP/packaged apps, the Settings app, Edge and WiX Burn
		# per-machine bundles keep working — EnableLUA=0 breaks all of
		# those on Win11. Make ADMIN elevation silent
		# (ConsentPromptBehaviorAdmin=0 = "elevate without prompting"),
		# no secure-desktop switch. Do NOT touch ConsentPromptBehaviorUser:
		# for STANDARD users the value 0 means "automatically DENY
		# elevation" (the opposite of the admin key) and yields "This app
		# has been blocked by your system administrator". Leaving it at
		# the Windows default is correct — our wizard account is an admin,
		# so only the admin key is relevant; if it is ever hit on the
		# user path that itself signals the account is not admin yet.
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System" /v EnableLUA /t REG_DWORD /d 1 /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System" /v ConsentPromptBehaviorAdmin /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System" /v PromptOnSecureDesktop /t REG_DWORD /d 0 /f
	};
	{
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System" /v LocalAccountTokenFilterPolicy /t REG_DWORD /d 1 /f;
		netsh.exe advfirewall firewall add rule name="LSW SMB" dir=in action=allow protocol=TCP localport=445 profile=any;
	};
	{
		Remove-Item -LiteralPath 'C:\Users\Public\Desktop\Microsoft Edge.lnk' -ErrorAction 'SilentlyContinue' -Verbose;
	};
	{
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU" /v AUOptions /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU" /v NoAutoRebootWithLoggedOnUsers /t REG_DWORD /d 1 /f;
	};
	{
		Register-ScheduledTask -TaskName 'MoveActiveHours' -Xml $( Get-Content -LiteralPath 'C:\Windows\Setup\Scripts\MoveActiveHours.xml' -Raw );
	};
	{
		# The 'lsw-agent' service is registered by the update script at
		# SetupComplete (post-OOBE, from LswPromote.ps1), NOT here in Specialize: registered
		# here with automatic start it would first run during OOBE, and
		# its install gate would have OOBE's own sessions to reason
		# about. (No HKLM\Run or logon-task autostart either: the
		# service starts the per-session helpers itself.)
	};
	{
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Dsh" /v AllowNewsAndInterests /t REG_DWORD /d 0 /f;
	};
	{
		reg.exe add "HKLM\Software\Policies\Microsoft\Windows\CloudContent" /v "DisableWindowsConsumerFeatures" /t REG_DWORD /d 1 /f;
	};
	{
		reg.exe add "HKLM\Software\Policies\Microsoft\Edge" /v HideFirstRunExperience /t REG_DWORD /d 1 /f;
	};
	{
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\ControlAnimations" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\AnimateMinMax" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\TaskbarAnimations" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\DWMAeroPeekEnabled" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\MenuAnimation" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\TooltipAnimation" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\SelectionFade" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\DWMSaveThumbnailEnabled" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\CursorShadow" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\ListviewShadow" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\ThumbnailsOrIcon" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\ListviewAlphaSelect" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\DragFullWindows" -Name 'DefaultValue' -Value 1 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\ComboBoxAnimation" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\FontSmoothing" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\ListBoxSmoothScrolling" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
		Set-ItemProperty -LiteralPath "Registry::HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\DropShadow" -Name 'DefaultValue' -Value 0 -Type 'DWord' -Force;
	};
	{
		reg.exe add "HKU\.DEFAULT\Control Panel\Accessibility\StickyKeys" /v Flags /t REG_SZ /d 10 /f;
	};
	{
		# No driver searches on Windows Update, from here on.
		#
		# The accel-virt device presents its host GPU's PCI vendor and
		# device IDs, so a guest with a network finds that vendor's real
		# WHQL driver on Windows Update, ranks it above the test-signed
		# avgpu and installs it over the device - which then bugchecks
		# at the next boot. provision.ps1's install stage turns driver
		# searches off too, but that is SetupComplete, and OOBE has had
		# the network and the device since the first boot. These are the
		# same policies it writes; it also stops the update services.
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate" /v ExcludeWUDriversInQualityUpdate /t REG_DWORD /d 1 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\DriverSearching" /v DontSearchWindowsUpdate /t REG_DWORD /d 1 /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching" /v SearchOrderConfig /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Device Metadata" /v PreventDeviceMetadataFromNetwork /t REG_DWORD /d 1 /f;
	};
	{
		# How much video memory the display adapter admits to.
		#
		# A VM with no GPU enumerates the Microsoft Basic Display
		# Adapter, whose HardwareInformation.MemorySize is 0 - and
		# applications gate their GPU path on that number long before
		# they ever open a driver. Photoshop's sniffer reads exactly
		# this key, reported "video RAM(MB): 0", and disabled the GPU
		# with a working OpenGL sitting underneath it. It is read from
		# the registry, not asked of any driver.
		#
		# What this reaches is whatever the Basic Display driver has
		# bound by specialize - the install-time VGA adapter. avgpu is
		# installed later, at SetupComplete, under a class key this
		# never sees.
		#
		# 1 GiB. Comfortably over the 256 MB minimum the applications
		# that check this ask for, and under the 4 GiB where the DWORD
		# form of it stops being representable. Takes effect with no
		# reboot.
		#
		# Both spellings, because consumers are split between them: the
		# QWORD is what a WDDM adapter reports today and the DWORD is
		# what the older path reads.
		#
		# This lives here rather than in a RunSynchronousCommand
		# because Path there is capped at 259 characters, and a longer
		# one does not fail on its own - setup rejects the WHOLE answer
		# file with 0x80220005 and the install dies at specialize.
		$class = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}';
		Get-ChildItem $class -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^[0-9]{4}$' } | ForEach-Object {
			New-ItemProperty -LiteralPath $_.PSPath -Name 'HardwareInformation.qwMemorySize' -Value 1073741824 -PropertyType QWord -Force;
			New-ItemProperty -LiteralPath $_.PSPath -Name 'HardwareInformation.MemorySize' -Value 1073741824 -PropertyType DWord -Force;
		};
		# The same values on 0000 whether or not it exists yet. The
		# adapter is enumerated by PnP, and on an image where that has
		# not happened by this point the loop above matches nothing and
		# writes nowhere; 0000 is the subkey the first adapter takes.
		New-Item -Path "$class\0000" -Force -ErrorAction SilentlyContinue | Out-Null;
		New-ItemProperty -LiteralPath "$class\0000" -Name 'HardwareInformation.qwMemorySize' -Value 1073741824 -PropertyType QWord -Force;
		New-ItemProperty -LiteralPath "$class\0000" -Name 'HardwareInformation.MemorySize' -Value 1073741824 -PropertyType DWord -Force;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to customize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\Specialize.log";

$scripts = @(
	{
		[System.Diagnostics.EventLog]::WriteEntry( 'UnattendGenerator', "User '$env:USERNAME' has requested to unlock the Start menu layout.", [System.Diagnostics.EventLogEntryType]::Information, 1 );
	};
	{
		Remove-Item -LiteralPath "${env:USERPROFILE}\Desktop\Microsoft Edge.lnk" -ErrorAction 'SilentlyContinue' -Verbose;
	};
	{
		reg.exe add "HKCU\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32" /ve /f;
	};
	{
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Search' -Name 'SearchboxTaskbarMode' -Type 'DWord' -Value 0;
	};
	{
		# "Adjust for best performance" less one effect, as Custom (3): a
		# window keeps its contents while it is dragged instead of leaving
		# an outline behind, which a mirrored window cannot follow. Each
		# value is the one the best-performance preset writes, set here
		# because a preset would be applied whole again.
		Set-ItemProperty -LiteralPath 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' -Name 'VisualFXSetting' -Type 'DWord' -Value 3 -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKEY_CURRENT_USER\Control Panel\Desktop' -Name 'UserPreferencesMask' -Type 'Binary' -Value ([byte[]](0x90, 0x12, 0x03, 0x80, 0x10, 0x00, 0x00, 0x00)) -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKEY_CURRENT_USER\Control Panel\Desktop' -Name 'DragFullWindows' -Type 'String' -Value '1' -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKEY_CURRENT_USER\Control Panel\Desktop\WindowMetrics' -Name 'MinAnimate' -Type 'String' -Value '0' -Force;
		foreach( $name in 'ListviewAlphaSelect', 'ListviewShadow', 'TaskbarAnimations' ) {
			Set-ItemProperty -LiteralPath 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name $name -Type 'DWord' -Value 0 -Force;
		}
		Set-ItemProperty -LiteralPath 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'IconsOnly' -Type 'DWord' -Value 1 -Force;
		# Not New-Item -Force on its own: on a key that exists, that
		# empties it.
		if( -not ( Test-Path -LiteralPath 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\DWM' ) ) {
			New-Item -Path 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\DWM' | Out-Null;
		}
		foreach( $name in 'EnableAeroPeek', 'AlwaysHibernateThumbnails' ) {
			Set-ItemProperty -LiteralPath 'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\DWM' -Name $name -Type 'DWord' -Value 0 -Force;
		}
	};
	{
		Get-Process -Name 'explorer' -ErrorAction 'SilentlyContinue' | Where-Object -FilterScript {
			$_.SessionId -eq ( Get-Process -Id $PID ).SessionId;
		} | Stop-Process -Force;
	};
	{
		New-Item -ItemType Directory -Force -Path 'C:\ProgramData\LSW' | Out-Null;
		# Record the wizard-chosen account name. The agent service reads
		# it (after Winlogon's AutoLogon DefaultUserName) to know whose
		# session is the wizard user's. installed.txt marks that this
		# per-user setup ran; nothing gates on it.
		Set-Content -LiteralPath 'C:\ProgramData\LSW\user.txt' -Value '{{user_name}}' -Encoding Ascii -Force;
		Set-Content -LiteralPath 'C:\ProgramData\LSW\installed.txt' -Value (Get-Date -Format s) -Encoding Ascii -Force;
	}
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to configure this user account. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "$env:TEMP\UserOnce.log";

$scripts = @(
	{
		reg.exe add "HKU\DefaultUser\Software\Policies\Microsoft\Windows\Explorer" /v "StartLayoutFile" /t REG_SZ /d "C:\Windows\Setup\Scripts\TaskbarLayoutModification.xml" /f;
		reg.exe add "HKU\DefaultUser\Software\Policies\Microsoft\Windows\Explorer" /v "LockedStartLayout" /t REG_DWORD /d 1 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "HideFileExt" /t REG_DWORD /d 0 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "Hidden" /t REG_DWORD /d 1 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "ShowSuperHidden" /t REG_DWORD /d 1 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Edge\SmartScreenEnabled" /ve /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Edge\SmartScreenPuaEnabled" /ve /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\AppHost" /v EnableWebContentEvaluation /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\AppHost" /v PreventOverride /t REG_DWORD /d 0 /f;
	};
	{
		$names = @(
		  'ContentDeliveryAllowed';
		  'FeatureManagementEnabled';
		  'OEMPreInstalledAppsEnabled';
		  'PreInstalledAppsEnabled';
		  'PreInstalledAppsEverEnabled';
		  'SilentInstalledAppsEnabled';
		  'SoftLandingEnabled';
		  'SubscribedContentEnabled';
		  'SubscribedContent-310093Enabled';
		  'SubscribedContent-338387Enabled';
		  'SubscribedContent-338388Enabled';
		  'SubscribedContent-338389Enabled';
		  'SubscribedContent-338393Enabled';
		  'SubscribedContent-353694Enabled';
		  'SubscribedContent-353696Enabled';
		  'SubscribedContent-353698Enabled';
		  'SystemPaneSuggestionsEnabled';
		);

		foreach( $name in $names ) {
		  reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v $name /t REG_DWORD /d 0 /f;
		}
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v TaskbarAl /t REG_DWORD /d 0 /f;
	};
	{
		$params = @{
		  LiteralPath = 'Registry::HKU\DefaultUser\Control Panel\Mouse';
		  Type = 'String';
		  Value = 0;
		  Force = $true;
		};
		Set-ItemProperty @params -Name 'MouseSpeed';
		Set-ItemProperty @params -Name 'MouseThreshold1';
		Set-ItemProperty @params -Name 'MouseThreshold2';
	};
	{
		reg.exe add "HKU\DefaultUser\Control Panel\Accessibility\StickyKeys" /v Flags /t REG_SZ /d 10 /f;
	};
	{
		# Screen saver off, no password on resume, for every account
		# created from here on. The tune-windows setup step writes the
		# same values to HKCU, but setup steps run as the agent service
		# (SYSTEM) now, whose HKCU is not the user's.
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v ScreenSaveActive /t REG_SZ /d 0 /f;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v ScreenSaverIsSecure /t REG_SZ /d 0 /f;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v ScreenSaveTimeOut /t REG_SZ /d 0 /f;
	};
	{
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\RunOnce" /v "UnattendedSetup" /t REG_SZ /d "powershell.exe -WindowStyle \""Normal\"" -ExecutionPolicy \""Unrestricted\"" -NoProfile -File \""C:\Windows\Setup\Scripts\UserOnce.ps1\""" /f;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to modify the default user’’s registry hive. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\DefaultUser.log";

$scripts = @(
	{
		Remove-Item -LiteralPath @(
		  'C:\Windows\Panther\unattend.xml';
		  'C:\Windows\Panther\unattend-original.xml';
		  'C:\Windows\Setup\Scripts\Wifi.xml';
		) -Force -ErrorAction 'SilentlyContinue' -Verbose;
	};
	{
		# Marker that the finalize scripts ran to completion. Useful
		# for diagnosing a half-finished install; nothing gates on it.
		#
		# It is NOT an OOBE-done sentinel and must not be used as one:
		# FirstLogonCommands is part of OOBE and runs while the
		# "Preparing Windows" screen is still displayed, so this file
		# appears well before there is a desktop. The agent decides
		# for itself when the session is usable by waiting on the
		# shell (see win::DesktopSession).
		New-Item -ItemType Directory -Force -Path 'C:\ProgramData\LSW' | Out-Null;
		Set-Content -LiteralPath 'C:\ProgramData\LSW\lsw-ready.flag' -Value (Get-Date -Format s) -Encoding Ascii -Force;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Id 0 -Activity 'Running scripts to finalize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $script.ToString().Trim() -replace '\s+', ' ' -replace '^(.{99})(.+)$', '$1…';
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 | Out-String -Width 1KB -Stream >> "C:\Windows\Setup\Scripts\FirstLogon.log";

$ErrorActionPreference = 'Continue';
New-Item -ItemType Directory -Force -Path 'C:\ProgramData\LSW' | Out-Null;
$log = 'C:\ProgramData\LSW\promote.log';
function L($m) { ('{0} {1}' -f (Get-Date -Format s), $m) | Add-Content -LiteralPath $log -Encoding Ascii; }
# LSW's files: the payload ISO carries what an update would ship (its
# \update), and the same script puts it in place, so that this guest ends
# with the same release.json as one that was updated. It goes first: it
# needs nothing from the account below, and the promotion has exits this
# must not sit behind.
#
# The script signs the driver package (which turns test signing on, effective
# from the next boot) and installs it with pnputil; avgpu.sys first starts
# on the first boot after setup, when the manager restarts the guest into
# its steady definition. It starts the agent, which keeps its port closed
# until the wizard user's desktop is usable. -NoRestart because Windows
# does not allow a restart from SetupComplete: the boot after setup is the
# restart (the result says restart:true in update-result.json).
#
# A failure leaves no release.json, so the first steady boot's GuestUpkeep
# (which finds the guest at no release) runs the update again, from the
# manager; nothing here retries.
$releaseId = '{{release}}';
$bundleVersion = '{{version}}';
$payload = [System.IO.DriveInfo]::GetDrives() | Where-Object { $_.DriveType -eq 'CDRom' -and $_.IsReady -and $_.VolumeLabel -eq 'LSW_PAYLOAD' } | Select-Object -First 1;
if (-not $payload) {
    L 'no LSW_PAYLOAD volume - nothing to update from';
} else {
    $stageDir = 'C:\ProgramData\LSW\update\' + $releaseId.Substring(0, 16);
    Remove-Item -LiteralPath $stageDir -Recurse -Force -ErrorAction SilentlyContinue;
    # xcopy without /K, on purpose: files on a CD carry the read-only
    # attribute and the sign stage rewrites avgpu.inf in place.
    $out = & xcopy.exe ($payload.RootDirectory.FullName + 'update') $stageDir /E /I /Y /Q 2>&1 | Out-String;
    L ('xcopy of ' + $payload.RootDirectory.FullName + 'update to ' + $stageDir + ' exited ' + $LASTEXITCODE + ': ' + $out.Trim());
    $updateScript = $stageDir + '\C\ProgramData\LSW\lsw-guest-update.ps1';
    if (-not (Test-Path -LiteralPath $updateScript)) {
        L ($updateScript + ' missing - the payload carried no update');
    } else {
        $out = & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $updateScript -Stage $stageDir -Release $releaseId -Version $bundleVersion -NoRestart 2>&1 | Out-String;
        L ('lsw-guest-update.ps1 exited ' + $LASTEXITCODE + ' - see update.log');
        if ($out) { $out.TrimEnd() | Add-Content -LiteralPath $log -Encoding Ascii; }
    }
}
$flag = 'C:\ProgramData\LSW\promoted.flag';
# SetupComplete.cmd can run twice on Win11 (SYSTEM during setup, then
# again post first-logon); the sentinel makes the second run a no-op.
if (Test-Path -LiteralPath $flag) { L 'promoted.flag present - skipping'; exit 0; }
$u = '{{user_name}}';
L ('SetupComplete promote start; target=' + $u + '; ctx=' + [System.Security.Principal.WindowsIdentity]::GetCurrent().Name);
# The account is created in the oobeSystem pass; SetupComplete normally
# runs after that, but guard the race with a bounded wait so we never
# deadlock OOBE (give up after ~5 min, exit 0).
$lu = $null; $n = 0;
while ($n -lt 60) {
    $lu = Get-LocalUser -Name $u -ErrorAction SilentlyContinue;
    if ($lu) { break; }
    Start-Sleep -Seconds 5; $n++;
}
if (-not $lu) { L 'account never materialized after 5 min - giving up'; exit 0; }
$members = @( Get-LocalGroupMember -Group 'Administrators' -ErrorAction SilentlyContinue | ForEach-Object { $_.SID.Value } );
if ($members -contains $lu.SID.Value) {
    L ('already a member: ' + $u);
} else {
    try {
        Add-LocalGroupMember -Group 'Administrators' -Member $lu -ErrorAction Stop;
        L ('ADDED ' + $u + ' to local Administrators');
    } catch {
        L ('Add-LocalGroupMember FAILED: ' + $_.Exception.Message);
        exit 0;
    }
}
Set-Content -LiteralPath $flag -Value (Get-Date -Format s) -Encoding Ascii -Force;
( Get-LocalGroupMember -Group 'Administrators' | Format-Table Name, SID -AutoSize | Out-String ) | Add-Content -LiteralPath $log -Encoding Ascii;
L 'SetupComplete promote done';
